import{_ as o,C as s,o as l,c as i,j as e,a as t,E as d,a3 as n}from"./chunks/framework.CZBGEXos.js";const x=JSON.parse('{"title":"Spreads","description":"","frontmatter":{},"headers":[],"relativePath":"uk/tools/spreads.md","filePath":"uk/tools/spreads.md"}'),h={name:"uk/tools/spreads.md"};function p(c,a,m,u,g,f){const r=s("Screenshot");return l(),i("div",null,[a[0]||(a[0]=e("h1",{id:"spreads",tabindex:"-1"},[t("Spreads "),e("a",{class:"header-anchor",href:"#spreads","aria-label":'Permalink to "Spreads"'},"​")],-1)),a[1]||(a[1]=e("p",null,[t("Spreads показує "),e("strong",null,"ту саму монету за різною ціною на різних біржах"),t(" просто зараз: наскільки широкий розрив, як довго він відкритий, а також обсяг і фандинг за кожною ціною.")],-1)),d(r,{src:"web-spreads",alt:"Spreads у веб-версії з кількома картками спредів",caption:"Spreads у веб-версії — у кутку спливаюче вікно нового лістингу"}),a[2]||(a[2]=n('<div class="info custom-block"><p class="custom-block-title">Раніше Alerts</p><p>До жовтня 2026 цей інструмент називався <strong>Alerts</strong> і також показував нові лістинги та ліквідації. Лістинги тепер — <a href="/manual/uk/getting-started.html#спливаючі-вікна-нових-лістингів">спливаючі вікна</a> в усіх інструментах, а ліквідації переїхали в <a href="/manual/uk/tools/ticks.html#ліквідаціі">Ticks</a>.</p></div><h2 id="як-читати-вікно" tabindex="-1">Як читати вікно <a class="header-anchor" href="#як-читати-вікно" aria-label="Permalink to &quot;Як читати вікно&quot;">​</a></h2><h3 id="панель-інструмента" tabindex="-1">Панель інструмента <a class="header-anchor" href="#панель-інструмента" aria-label="Permalink to &quot;Панель інструмента&quot;">​</a></h3><p>Панель показує налаштування, що діють. У веб-версії кожен чип — швидкий фільтр, який можна змінити на місці:</p><ul><li><strong>Таймфрейм</strong> — інтервал свічок графіків карток, наприклад <code>1m chart</code>.</li><li><strong>Spread ≥ …</strong> — <a href="#minimum-spread">мінімальний спред</a>.</li><li><strong>Max age</strong> — <a href="#max-spread-age">max spread age</a>; <code>Any age</code>, коли вимкнено.</li><li><strong>Max width</strong> — <a href="#max-spread">max spread %</a>; <code>Any width</code>, коли вимкнено.</li><li><strong>Volume</strong> — <a href="#volume-filter">фільтр обсягу</a>; <code>Any volume</code>, коли вимкнено.</li><li><strong>Сортування</strong> — порядок карток: <strong>Newest</strong>, <strong>Spread</strong>, <strong>Age</strong> або <strong>Volume</strong>.</li></ul><h3 id="порядок" tabindex="-1">Порядок <a class="header-anchor" href="#порядок" aria-label="Permalink to &quot;Порядок&quot;">​</a></h3><p>За замовчуванням картки впорядковані від найновіших, за <strong>часом відкриття спреду</strong>. Картка зберігає місце, поки оновлюються її числа, тож стрічка не перемішується, поки ви читаєте. У веб-версії можна натомість сортувати за найширшим спредом, найдовше відкритим або найбільшим сумарним обсягом.</p><h3 id="картка-спреду" tabindex="-1">Картка спреду <a class="header-anchor" href="#картка-спреду" aria-label="Permalink to &quot;Картка спреду&quot;">​</a></h3><ul><li><p><strong>Символ</strong> — натисніть, щоб скопіювати в буфер обміну.</p></li><li><p><strong>Вік</strong> — як довго спред на рівні вашого порогу або вище, наприклад <code>12m</code> чи <code>3h</code>.</p></li><li><p><strong>Спред</strong> — поточний максимальний розрив цін між біржами у відсотках.</p></li><li><p><strong>Рядки бірж</strong> — по рядку на кожну біржу, де є монета, з кольоровою крапкою як у її лінії на графіку:</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Значення</th></tr></thead><tbody><tr><td>Exchange</td><td>Звідки ціна</td></tr><tr><td>24h vol</td><td>Обсяг біржі за 24 години. Заливка показує її частку в сумарному обсязі монети на цих біржах</td></tr><tr><td>Funding</td><td>Поточна ставка фандингу — зелена, коли платять лонги, червона, коли шорти</td></tr><tr><td>Next</td><td>Час до наступної виплати фандингу на цій біржі</td></tr></tbody></table></li><li><p><strong>Графік</strong> — по лінії ціни на кожну біржу, щоб бачити, розрив розширюється, звужується чи тримається.</p></li><li><p><strong>Повний екран</strong> — кнопка розгортання відкриває картку на весь розмір; див. <a href="#повноекраннии-режим">Повноекранний режим</a>.</p></li></ul><h4 id="притлумлені-картки" tabindex="-1">Притлумлені картки <a class="header-anchor" href="#притлумлені-картки" aria-label="Permalink to &quot;Притлумлені картки&quot;">​</a></h4><p>Картка стає <strong>притлумленою</strong>, коли поточний спред опускається нижче вашого <a href="#minimum-spread">мінімального спреду</a>. Спред ще не закінчився — сервер тримає його відкритим, доки він не пробуде нижче порогу <strong>10 хвилин</strong>. Якщо він знову розшириться, картка засвітиться знову й збереже свій вік. Якщо ні — зникне зі стрічки.</p><p>Звук грає один раз на новий спред, а не знову, коли притлумлена картка повертається.</p><h4 id="як-рахується-спред" tabindex="-1">Як рахується спред <a class="header-anchor" href="#як-рахується-спред" aria-label="Permalink to &quot;Як рахується спред&quot;">​</a></h4><p>Відсоток — це <code>(найвища ціна − найнижча ціна) ÷ найнижча ціна × 100</code> по всіх біржах, що зараз дають ціну цієї монети.</p><p>Це значення <strong>живе</strong>. Воно постійно перераховується з тих самих потоків бірж, що живлять лінії графіка, тож показує поточний розрив, а не той, що був у мить відкриття.</p><p>Два види цін не враховуються, бо жоден із них — не розрив, на якому можна торгувати:</p><ul><li><strong>Завмерла ціна.</strong> Біржа, де за цілу 5-хвилинну свічку не було жодної угоди з монетою, вилучається зі спреду — делістнутий контракт у розрахунку годинами транслює останню ціну.</li><li><strong>Інший актив з тією ж назвою.</strong> Ціна, більша за серединну по біржах більш ніж удвічі або менша за її половину, вважається іншою монетою з тим самим тікером (наприклад, акційний ф&#39;ючерс і криптотокен, обидва <code>BB</code>) і вилучається. Якщо лишаються лише дві біржі й вони так розходяться, монета не показується взагалі.</li></ul><div class="warning custom-block"><p class="custom-block-title">Спред — не гарантований прибуток</p><p>Це різниця між двома котируваннями. Вона нічого не каже про те, чи можна на ній реально заробити — глибина стакана, комісії, фандинг, час переказу й доступність виведення в розрахунок не входять, а видимий розрив може закритися раніше, ніж виконається ордер. Сприймайте це як сигнал подивитися, а не як результат.</p></div><p>Графік навмисно збільшений з тісними полями ціни, бо розрив між лініями бірж зазвичай малий відносно ціни й за звичайного масштабу був би непомітний.</p><h3 id="повноекраннии-режим" tabindex="-1">Повноекранний режим <a class="header-anchor" href="#повноекраннии-режим" aria-label="Permalink to &quot;Повноекранний режим&quot;">​</a></h3><p>Кнопка розгортання відкриває картку на весь розмір: ті самі лінії цін по біржах, рядки бірж з обсягом і фандингом, поточний спред і його вік. Таймфрейм вибирається вгорі. У веб-версії повноекранний графік також має <a href="/manual/uk/getting-started.html#рисування-в-повноекранному-режимі">інструменти рисування</a>; рисунки тут зберігаються для кожної монети окремо від інших інструментів. Натисніть <kbd>Esc</kbd> або кнопку закриття, щоб вийти.</p><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>Відкрийте налаштування Spreads: іконка праворуч на панелі інструмента (веб) або вкладка <strong>Spreads</strong> у головному вікні (Windows).</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>Скільки карток показує стрічка одночасно. Діапазон <strong>від 3 до 50</strong>, за замовчуванням 9.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>Інтервал свічок для ліній цін у картках. Варіанти: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>. За замовчуванням <code>1m</code>.</p><p>Це змінює лише графік. На розрахунок спреду й на те, які спреди проходять, не впливає.</p><h3 id="spread-settings" tabindex="-1">Spread settings <a class="header-anchor" href="#spread-settings" aria-label="Permalink to &quot;Spread settings&quot;">​</a></h3><h4 id="minimum-spread" tabindex="-1">Minimum spread <a class="header-anchor" href="#minimum-spread" aria-label="Permalink to &quot;Minimum spread&quot;">​</a></h4><p>Спред, якого має досягти монета, щоб з&#39;явитися. Діапазон <strong>від 1% до 10%</strong> з кроком 0,5%, за замовчуванням 1%.</p><p>Спред, що опустився нижче цього значення, <a href="#притлумлені-картки">притлумлюється</a>, а не зникає одразу. Він покидає стрічку після 10 хвилин нижче порогу.</p><h4 id="max-spread" tabindex="-1">Max spread % <a class="header-anchor" href="#max-spread" aria-label="Permalink to &quot;Max spread %&quot;">​</a></h4><p>Приховує спреди, ширші за це значення. За замовчуванням <strong>вимкнено</strong> (порожньо). Кнопки − / + змінюють на 5%, або введіть будь-яке значення.</p><p>Спред у сотні відсотків майже ніколи не є реальною можливістю. Сервер уже вилучає <a href="#як-рахується-спред">інші активи з тією ж назвою</a>, але обмеження все одно допомагає з рештою. <strong>50%</strong> — хороша відправна точка.</p><h4 id="max-spread-age" tabindex="-1">Max spread age <a class="header-anchor" href="#max-spread-age" aria-label="Permalink to &quot;Max spread age&quot;">​</a></h4><p>Приховує спреди, відкриті довше за це значення. Кроки: <strong>Off</strong>, 30m, 1h, 2h, 4h, 8h, 12h, 1d, 2d, 3d, 7d. За замовчуванням Off.</p><p>Розрив, що тримається днями, зазвичай структурний — призупинене виведення, інший токен, — а не той, що закриється.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="new-spread-sound" tabindex="-1">New spread sound <a class="header-anchor" href="#new-spread-sound" aria-label="Permalink to &quot;New spread sound&quot;">​</a></h4><p>Відтворює звук, коли відкривається новий спред. Увімкнено за замовчуванням.</p><h3 id="volume-filter" tabindex="-1">Volume filter <a class="header-anchor" href="#volume-filter" aria-label="Permalink to &quot;Volume filter&quot;">​</a></h3><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Фільтрує спреди за обсягом торгів за 24 години. За замовчуванням вимкнено.</p><div class="info custom-block"><p class="custom-block-title">Потрібно дві</p><p>Спред має мати <strong>щонайменше дві біржі</strong> з обсягом вище мінімального, щоб пройти фільтр. Це навмисно: розрив цін має сенс, лише якщо за обома його сторонами є реальна торгівля.</p></div><h4 id="minimum-24h-volume" tabindex="-1">Minimum 24h volume <a class="header-anchor" href="#minimum-24h-volume" aria-label="Permalink to &quot;Minimum 24h volume&quot;">​</a></h4><p>Обсяг за 24 години в USD, потрібний біржі, щоб її сторона спреду рахувалася. Введіть суму; за замовчуванням <strong>$1 000 000</strong>.</p><p>Неактивне, поки фільтр обсягу вимкнено.</p><div class="info custom-block"><p class="custom-block-title">Усі ці фільтри працюють на сервері</p><p>Мінімальний спред, max spread %, max age і фільтр обсягу застосовуються на сервері, тож прихований спред узагалі не доходить до застосунку. Зміна значення діє протягом секунди.</p></div><h2 id="пов-язане" tabindex="-1">Пов&#39;язане <a class="header-anchor" href="#пов-язане" aria-label="Permalink to &quot;Пов&#39;язане&quot;">​</a></h2><ul><li><a href="/manual/uk/tools/knives.html">Knives</a> — рух ціни на одній біржі, а не розриви між біржами</li><li><a href="/manual/uk/tools/monitor.html">Monitor</a> — ранжований огляд ринку</li><li><a href="/manual/uk/getting-started.html#спливаючі-вікна-нових-лістингів">Спливаючі вікна нових лістингів</a> — раніше частина цього інструмента</li></ul>',52))])}const k=o(h,[["render",p]]);export{x as __pageData,k as default};
